# Validation
@app.get('/products/')
def list_products(
    min_price: float = Query(ge=0, description='Minimum price'),
    max_price: float = Query(ge=0, le=10000),
    category: str = Query(min_length=2, max_length=50),
    tags: list[str] = Query(default=[], alias='tag'),
    in_stock: bool = Query(default=True),
    sort_by: str = Query(default='name', regex='^(name|price|date)$')
):
    return {
        'min_price': min_price,
        'max_price': max_price,
        'category': category,
        'tags': tags,
        'in_stock': in_stock,
        'sort_by': sort_by
    }

