Multiple Parameters:
from fastapi import FastAPI, Path, Query
from pydantic import BaseModel
from typing import Optional

app = FastAPI()

class Item(BaseModel):
    name: str
    description: Optional[str] = None
    price: float
    tax: Optional[float] = None

class User(BaseModel):
    username: str
    full_name: Optional[str] = None

# Mix path, query, body
@app.put('/items/{item_id}')
def update_item(
    item_id: int = Path(ge=1),
    item: Item = None,
    user: User = None,
    importance: int = Query(ge=1, le=10),
    q: Optional[str] = None
):
    results = {'item_id': item_id, 'item': item, 'user': user}
    results['importance'] = importance
    if q:
        results['q'] = q
    return results

# Single body parameter
@app.post('/items/')
def create_item(item: Item):
    return item

# Body with singular value
from fastapi import Body

@app.put('/items/{item_id}')
def update_item_body(
    item_id: int,
    item: Item,
    user: User,
    importance: int = Body(ge=1),
):
    return {'item_id': item_id, **item.model_dump(), 'importance': importance}

# Embed single body parameter
# Without embed: POST /items/ with body {"name": "Foo"}
# With embed: POST /items/ with body {"item": {"name": "Foo"}}
@app.put('/items/embed/{item_id}')
def update_item_embed(
    item_id: int,
    item: Item = Body(embed=True)
):
    return {'item_id': item_id, 'item': item}

Field Validation:
from pydantic import BaseModel, Field, field_validator, model_validator
from typing import Optional

class UserCreate(BaseModel):
    username: str = Field(..., min_length=3, max_length=20, pattern='^[a-zA-Z0-9_]+$')
    email: str = Field(..., max_length=100)
    password: str = Field(..., min_length=8)
    password_confirm: str
    age: int = Field(ge=13, le=120)
    website: Optional[str] = Field(None, pattern='^https?://')

    @field_validator('email')
    @classmethod
    def validate_email(cls, v: str) -> str:
        if '@' not in v:
            raise ValueError('Invalid email address')
        return v.lower()

    @field_validator('username')
    @classmethod
    def username_alphanumeric(cls, v: str) -> str:
        if not v.isalnum():
            raise ValueError('Username must be alphanumeric')
        return v

    @model_validator(mode='after')
    def check_passwords_match(self) -> 'UserCreate':
        if self.password != self.password_confirm:
            raise ValueError('Passwords do not match')
        return self


# Usage in endpoint
@app.post('/users/', response_model=UserCreate)
def create_user(user: UserCreate):
    return user

