Response & Status Codes:
from fastapi import FastAPI, status
from fastapi.responses import JSONResponse, HTMLResponse, FileResponse
from pydantic import BaseModel
from typing import Optional, List

class ItemOut(BaseModel):
    id: int
    name: str
    price: float
    discount_price: Optional[float] = None

class ItemIn(BaseModel):
    name: str
    price: float

app = FastAPI()

# response_model filters and validates output
@app.post('/items/', response_model=ItemOut, status_code=status.HTTP_201_CREATED)
def create_item(item: ItemIn):
    return ItemOut(id=1, **item.model_dump())

# Exclude unset fields (for PATCH)
@app.patch('/items/{item_id}', response_model=ItemOut, response_model_exclude_unset=True)
def patch_item(item_id: int, item: ItemIn):
    return ItemOut(id=item_id, **item.model_dump())

# Custom status codes
@app.get('/items/', status_code=200)
def list_items() -> List[ItemOut]:
    return [ItemOut(id=1, name='Foo', price=10.0)]

@app.delete('/items/{item_id}', status_code=status.HTTP_204_NO_CONTENT)
def delete_item(item_id: int):
    return None

# Different response types
@app.get('/html')
def get_html() -> HTMLResponse:
    return HTMLResponse('<h1>Hello</h1>')

@app.get('/download')
def download():
    return FileResponse('report.pdf', filename='report.pdf')

@app.get('/json')
def custom_json():
